        "clippy::large_enum_variant",
        "clippy::doc_markdown",
        "clippy::doc_lazy_continuation",
        "clippy::struct_field_names",
        "clippy::use_self",
        "rustdoc::broken_intra_doc_links",
    ] {
        let _ = writeln!(source, "#![allow({lint})]");
    }
