    "draft" / "CallToolResult" as call_tool_result_draft
        : protocol_droid_schema::wire::draft::CallToolResult,
    "draft" / "ToolChoice" as tool_choice_draft
        : protocol_droid_schema::wire::draft::ToolChoice,
    "draft" / "Icon" as icon_draft
        : protocol_droid_schema::wire::draft::Icon,
    "draft" / "ElicitRequestFormParams" as elicit_form_draft
        : protocol_droid_schema::wire::draft::ElicitRequestFormParams,
    "draft" / "ServerCapabilities" as server_capabilities_draft
        : protocol_droid_schema::wire::draft::ServerCapabilities,
}

/// One property test per `(revision, definition)` pair, for every pair.
///
/// The table this macro is handed is generated by `build.rs` from the vendored
/// schemas, so it names every definition every revision defines. The
/// hand-written table above is the complement: it names the types by hand,
/// which is what turns the definition-to-type mapping into a compile-checked
/// fact. This one is generated, which is what turns the *values* into
/// exhaustive coverage — a definition nobody thought to write down is still
/// round-tripped.
///
/// The pairs are recorded as well as tested, so a test can assert that the
/// table covers what the schemas define. A table that silently lost a
/// definition would leave a hole in the coverage that nothing reports.
macro_rules! exhaustive_round_trips {
    ($($revision:literal / $definition:literal as $test:ident : $ty:ty),* $(,)?) => {
        /// Every `(revision, definition)` pair the generated table covers.
        const COVERED_PAIRS: &[(&str, &str)] = &[
            $(($revision, $definition),)*
        ];

        $(
            proptest! {
                // The same configuration as the hand-written table above: no
                // failure persistence, because an integration test target has
                // no `lib.rs` to anchor the regression file to.
                #![proptest_config(proptest::test_runner::Config {
                    cases: CASES,
                    failure_persistence: None,
                    ..proptest::test_runner::Config::default()
                })]
                #[test]
                fn $test(value in values($revision, $definition)) {
                    assert_round_trips::<$ty>($revision, $definition, &value);
                }
            }
        )*
    };
}

// The generated table. `build.rs` writes it from the vendored schemas, so it
// cannot drift from them: a revision that gains a definition gains a case.
include!(concat!(env!("OUT_DIR"), "/property_cases.rs"));

/// The vendored revisions, in directory order.
///
/// A directory under `spec/` counts when it holds a `schema.json`. The
/// `cited/`, `a2a/` and `acp/` trees hold documents and other protocols'
/// schemas rather than MCP revisions, and none of them has a `schema.json` of
/// its own, so they are excluded by the rule rather than by a list.
fn vendored_revisions() -> Vec<String> {
    let Ok(entries) = std::fs::read_dir(spec_dir()) else {
        return Vec::new();
    };
    let mut revisions: Vec<String> = entries
        .filter_map(Result::ok)
        .filter(|entry| entry.path().join("schema.json").is_file())
        .filter_map(|entry| entry.file_name().into_string().ok())
        .collect();
    revisions.sort();
    revisions
}

/// The generated table covers every definition every revision defines.
///
/// This is the check that makes the generated table worth trusting. The table
/// is produced by the build script from the same schemas the property cases
/// read, so a definition the table missed would leave a hole in the coverage
/// that no other test reports — and a hole nobody reports is the same as no
/// coverage at all.
#[test]
fn the_generated_table_covers_every_definition() -> Result<(), String> {
    let expected: std::collections::BTreeSet<(String, String)> = vendored_revisions()
        .into_iter()
        .flat_map(|revision| {
            defs_for(&revision)
                .keys()
                .map(|definition| (revision.clone(), definition.clone()))
                .collect::<Vec<_>>()
        })
        .collect();

    let covered: std::collections::BTreeSet<(String, String)> = COVERED_PAIRS
        .iter()
        .map(|(revision, definition)| ((*revision).to_owned(), (*definition).to_owned()))
        .collect();

    let missing: Vec<(String, String)> = expected.difference(&covered).cloned().collect();
    let extra: Vec<(String, String)> = covered.difference(&expected).cloned().collect();

    if missing.is_empty() && extra.is_empty() {
        return Ok(());
    }
    Err(format!(
        "the generated table does not match the vendored schemas\n  \
         {} pair(s) missing: {missing:?}\n  {} pair(s) not in any schema: {extra:?}",
        missing.len(),
        extra.len()
    ))
}

