import json, os, collections

def to_snake(name):
    out = []
    for i, ch in enumerate(name):
        if ch.isascii() and ch.isupper():
            if i > 0: out.append('_')
            out.append(ch.lower())
        elif ch.isascii() and ch.isalnum():
            out.append(ch)
        else:
            out.append('_')
    return ''.join(out)

RESERVED = set("""abstract as async await become box break const continue crate do dyn else
enum extern false final fn for if impl in let loop macro match mod move mut override priv pub
ref return self Self static struct super trait true try type typeof union unsafe unsized use
virtual where while yield""".split())

names = set(); defs = set()
for d in sorted(os.listdir('crates/protocol-droid-schema/spec')):
    p = f'crates/protocol-droid-schema/spec/{d}/schema.json'
    if not os.path.isfile(p): continue
    s = json.load(open(p))
    defs.update((s.get('definitions') or {}).keys())
    def walk(node):
        if isinstance(node, dict):
            for k, v in node.items():
                if k == 'properties' and isinstance(v, dict): names.update(v.keys())
                walk(v)
        elif isinstance(node, list):
            for v in node: walk(v)
    walk(s.get('definitions') or {})

print("=== property names whose snake form is a RESERVED word ===")
hits = [(n, to_snake(n)) for n in sorted(names) if to_snake(n) in RESERVED]
for n, s in hits: print(f"   {n!r} -> snake {s!r}  (in RESERVED)")
if not hits: print("   (none)")

print("\n=== property names whose snake form is one of the 4 non-raw words ===")
NR = {"self","super","crate"}
h2 = [(n, to_snake(n)) for n in sorted(names) if to_snake(n) in NR]
for n,s in h2: print(f"   {n!r} -> {s!r}")
if not h2: print("   (none)")

print("\n=== property names whose snake form is 'gen' ===")
h3 = [n for n in sorted(names) if to_snake(n) == 'gen']
print("   ", h3 if h3 else "(none)")

print("\n=== definition names that are RESERVED or lowercase 'gen' ===")
h4 = [d for d in sorted(defs) if d in RESERVED or d == 'gen']
print("   ", h4 if h4 else "(none)")

print("\n=== collision check over property names under the NEW rule ===")
def new_field(name):
    s = to_snake(name)
    if s in NR: return s + "_"
    if s in RESERVED: return "r#" + s
    if s.startswith('_'): return s.lstrip('_')
    return s

seen = collections.defaultdict(list)
for n in names: seen[new_field(n)].append(n)
coll = {k:v for k,v in seen.items() if len(v) > 1}
print(f"   {len(names)} names -> {len(seen)} distinct fields; collisions: {len(coll)}")
for k,v in coll.items(): print(f"      {k}: {v}")
