            hex_digest(schema_body.as_bytes()),
            hex_digest(changelog_body.as_bytes()),
        ));
        let content = vec![
            ("2025-06-18/schema.json", schema_body.to_owned()),
            ("2025-06-18/CHANGELOG.md", changelog_body.to_owned()),
        ];
        (source, content)
