 /// a member named `Self` arrives here as `self` and is covered by that entry.
 const NOT_RAW_IDENTIFIABLE: &[&str] = &["self", "super", "crate"];

 fn is_keyword(name: &str) -> bool {
     RESERVED.contains(&name)
 }

